package com.ibm.catalog;

import java.util.Collection;
import javax.persistence.Cacheable;
import javax.persistence.Entity;
import javax.persistence.FetchType;
import javax.persistence.JoinColumn;
import javax.persistence.ManyToOne;
import javax.persistence.NamedQuery;
import javax.persistence.OneToMany;
import io.quarkus.hibernate.orm.panache.PanacheEntity;
import javax.json.bind.annotation.JsonbTransient;

@Entity
@Cacheable
@NamedQuery(name="top.level.category",query="select c from Category c where c.parent IS NULL")
public class Category extends PanacheEntity {

    public Category() {}

    public String name;

    @ManyToOne(fetch=FetchType.EAGER)
	@JoinColumn(name="parent")
    public Category parent;

    @OneToMany(mappedBy="parent",fetch=FetchType.EAGER)
	private Collection<Category> subCategories;

    public Collection<Category> getSubCategories() {
		return subCategories;
	}

	public void setSubCategories(Collection<Category> subCategories) {
		this.subCategories = subCategories;
    }

    @JsonbTransient
	public Category getParent() {
		return parent;
	}

	public void setParent(Category parent) {
		this.parent = parent;
	}
}

package com.ibm.catalog;

import java.util.List;
import javax.enterprise.context.ApplicationScoped;
import javax.inject.Inject;
import javax.json.Json;
import javax.ws.rs.GET;
import javax.ws.rs.Path;
import javax.ws.rs.Produces;
import javax.ws.rs.WebApplicationException;
import javax.ws.rs.core.Response;
import javax.ws.rs.ext.ExceptionMapper;
import javax.ws.rs.ext.Provider;
import javax.persistence.EntityManager;
import javax.persistence.Query;

@Path("/CustomerOrderServicesWeb/jaxrs/Category")
@ApplicationScoped
@Produces("application/json")
public class CategoryResource {

    @Inject
    protected EntityManager em;

    @GET
    public List<Category> get() {
        System.out.println("/CustomerOrderServicesWeb/jaxrs/Category invoked in Quarkus catalog service");

        Query query = em.createNamedQuery("top.level.category");
        List<Category> categories = query.getResultList();
        return categories;
    }


    @Provider
    public static class ErrorMapper implements ExceptionMapper<Exception> {

        @Override
        public Response toResponse(Exception exception) {
            int code = 500;
            if (exception instanceof WebApplicationException) {
                code = ((WebApplicationException) exception).getResponse().getStatus();
            }
            return Response.status(code)
                    .entity(Json.createObjectBuilder().add("error", exception.getMessage()).add("code", code).build())
                    .build();
        }
    }
}

package com.ibm.catalog;

import java.math.BigDecimal;
import javax.persistence.Cacheable;
import javax.persistence.Entity;
import io.quarkus.hibernate.orm.panache.PanacheEntity;
import java.util.Collection;
import javax.persistence.FetchType;
import javax.persistence.JoinColumn;
import javax.persistence.JoinTable;
import javax.persistence.ManyToMany;
import javax.json.bind.annotation.JsonbTransient;
import javax.persistence.NamedNativeQuery;

@Entity
@Cacheable
@NamedNativeQuery(name="product.by.cat.or.sub",
		query="select distinct p.id,p.name,p.price,p.description,p.image from product as p,productcategory as pc, category as c where (c.id = ? or c.parent = ?) AND pc.categoryid = c.id AND pc.productid = p.id",
		resultClass=Product.class)
public class Product extends PanacheEntity {

    public Product() {}

	public BigDecimal price;

	public String name;

	public String description;

	public String image;

	@ManyToMany(fetch=FetchType.EAGER)
	@JoinTable(name="productcategory",joinColumns={@JoinColumn(name="productid")},inverseJoinColumns={@JoinColumn(name="categoryid")})	
	public Collection<Category> categories;

	@JsonbTransient
	public Collection<Category> getCategories() {
		return categories;
	}

	@JsonbTransient
	public void setCategories(Collection<Category> categories) {
		this.categories = categories;
	}
}

